-- F11a: source summaries (Visa Ops, 2026-10-16) + two new rows + family step mapping.
-- GENERATED from docs/sources/F11-source-summaries.csv (32 rows) and /workspace/F11-visa-ops-copy.md.
-- Apply scope: local + nomade-dev ONLY. not nomade-prod until F11a launch.

alter table internal.sources
  add column if not exists summary text check (summary is null or length(summary) <= 800),
  add column if not exists summary_reviewed_at date,
  add column if not exists summary_uncertain boolean not null default false;

comment on column internal.sources.summary is
  'F11: Visa Ops paraphrase of the official page (<=800 chars). Grounding text for Ask (F11b). Not legal advice.';
comment on column internal.sources.summary_reviewed_at is 'F11: date Visa Ops reviewed summary.';
comment on column internal.sources.summary_uncertain is 'F11: Visa Ops flagged the summary as partial/uncertain (page did not fully render, stale file, etc.).';

-- F11: "inactive" = recorded but not public/citable until Visa Ops confirms (e.g. URL).
alter table internal.sources drop constraint if exists sources_status_check;
alter table internal.sources add constraint sources_status_check
  check (status in ('active', 'stale', 'retired', 'inactive'));

update internal.sources set summary = 'Agenzia delle Entrate page (last updated 7 March 2025) explaining the codice fiscale: a 16-character code that identifies people in dealings with public bodies. It says that for foreign citizens who apply for or renew a permesso di soggiorno, the Questura assigns the code; residents abroad can ask an Italian consulate. People without a code can request one with form AA4/8 by PEC or at any Agenzia office by appointment; a non-EU applicant attaches a valid passport with visa, a valid permesso, or another listed ID. A first code for a foreign citizen needs an in-person appointment for identification. A certificate of assignment is issued while the Tessera Sanitaria or code card is pending.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-ade-codice-fiscale';
update internal.sources set summary = 'Agenzia delle Entrate information sheet (last updated 30 October 2023). To open, change, or close a partita IVA for a professional activity or other activity that does not require registration in the Registro delle imprese or the REA, an individual fills in and sends form AA9/12 to the Agenzia. For a business or craft activity, it says to use the Comunicazione Unica d''impresa (an Infocamere service), which also handles registration in the Registro delle imprese or REA. The page does not mention visas or digital nomads.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-ade-partita-iva-aa9';
update internal.sources set summary = 'Agenzia delle Entrate page on how to open a partita IVA for a professional activity not requiring Registro delle imprese registration. Form AA9/12 is filed within 30 days of the start of the activity: by PEC (subject ''Dichiarazione di inizio attività'', with ID copy if signed by hand), in person or by delegate at any Agenzia office by appointment, or by registered mail with an ID copy. It adds a special rule for non-EU/EEA residents who appoint a tax representative (filing only at that representative''s provincial office, with set declarations and guarantees), and says the form can be prepared with Agenzia software and sent online from the reserved area. The page does not mention visas or digital nomads.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-ade-partita-iva-howto';
update internal.sources set summary = 'Gazzetta Ufficiale text of the interministerial decree of 29 February 2024 (Interior, Foreign Affairs, Tourism, Labour), preamble and Art. 1. Art. 1 says the decree sets how to enter and get a permesso di soggiorno, which highly qualified workers can benefit, the minimum income limits, and how the work is verified. It applies to non-EU citizens doing highly qualified work remotely with technology, either self-employed or for a company that may be outside Italy. Entry and stay over 90 days is allowed outside the annual quotas, without prejudice to art. 27-quater and 27-quinquies routes; for stays under 90 days the visa and permesso under Arts. 3 and 4 are still needed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-gu-dm-2024-02-29-art1';
update internal.sources set summary = 'Art. 2 of the 29 February 2024 decree (definitions). A ''digital nomad'' is a foreigner doing self-employed work (lavoro autonomo) remotely through technology. A ''remote worker'' is a foreigner doing subordinate (employee) work or collaboration remotely, under art. 2(1) of D.Lgs. 81/2015. ''Highly qualified work'' means work by someone meeting art. 27-quater(1) of D.Lgs. 286/1998. A ''company, even if not resident in Italy'' is an employer or client that professionally runs an organised economic activity and may have its registered office outside Italy. A third-country national is anyone who is not an EU citizen.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-gu-dm-2024-02-29-art2';
update internal.sources set summary = 'Art. 3 of the 29 February 2024 decree (requirements for the visa and permesso). Workers must: have minimum annual income from lawful sources not below three times the minimum level for exemption from healthcare cost-sharing (no euro figure); health insurance for medical care and hospital stays valid in Italy for the stay; suitable documentation on housing; at least six months'' prior experience in the work; and, for remote workers, the work or collaboration contract or binding offer for work needing an art. 27-quater qualification. No provisional nulla osta (nomads) or work nulla osta (remote workers) is needed. The visa is refused or revoked if an employer resident in Italy has listed convictions in the last five years; the applicant files the employer''s signed declaration with ID.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-gu-dm-2024-02-29-art3';
update internal.sources set summary = 'Art. 4 of the 29 February 2024 decree (permesso di soggiorno). The holder of the visa must request the permesso directly at the Questura of the province where they are, within eight working days of entry. It reads ''nomade digitale - lavoratore da remoto'', lasts no more than one year, and is renewable yearly if the conditions remain. The holder shows the visa documents stamped by the consulate. It is refused or revoked if requirements lapse, if tax and contribution rules are not respected, or if the employer has listed convictions. Family reunification is allowed for the relatives in art. 29(1)(a) and (b) of the Testo unico, under the conditions of art. 29; they get a family permesso of the same length as the worker''s. The Questura sends the contract to the labour inspectorate.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-gu-dm-2024-02-29-art4';
update internal.sources set summary = 'Art. 6 of the 29 February 2024 decree (tax compliance). For digital nomads and remote workers, the Questura generates and communicates the codice fiscale when it issues the permesso. Digital nomads must also request a partita IVA under art. 35 of DPR 633/1972; no deadline is set in this article and remote workers are not mentioned for it. The Questura notifies the Agenzia delle Entrate of the permesso electronically. Ordinary tax-audit rules apply, and the Agenzia informs the Questura if tax violations are found.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-gu-dm-2024-02-29-art6';
update internal.sources set summary = 'Prefettura di Roma page (last updated 21 May 2024) on registering at the anagrafe. An adult family member registers in person at the Comune where they live, also declaring minor children. Needed: a permesso valid over 3 months, a valid passport, the codice fiscale, and civil-status papers not shown in the passport (birth, marriage, etc.), translated and legalised. Registration is completed after local police confirm you live at the address. Registration is needed for things like a driving licence and the national health service. Other points: data must match across passport and permesso; renew the residence declaration within 60 days of renewing the permesso; moving Comune is filed within 20 days; how to get an identity card.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-interno-prefettura-roma-anagrafe';
update internal.sources set summary = 'Foreign Ministry ''Il visto per l''Italia'' page on rights and duties for long stays over 90 days. It has a menu of visa types (it lists categories such as lavoro autonomo, lavoro subordinato, motivi familiari; no digital-nomad entry was visible). The text loaded today showed the ''Missione'' section on sending a permesso request via authorised post offices, plus general warnings: non-EU citizens with a regular permesso must register at the anagrafe of their Comune; the integration agreement for permits of at least one year; and health cover rules (mandatory national health service enrolment for some purposes, insurance or voluntary enrolment for others). Other tab contents may load dynamically and were not confirmed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = true where id = 'it-maeci-long-stay-visa-d';
update internal.sources set summary = 'The public page at this URL is a login screen for the Prenot@Mi portal: it asks the user to log in, offers password recovery and resending the activation email, and a registration link for first-time users, plus terms and conditions. Nothing about visa types, appointments, or availability is visible without logging in. Other active sources (US consular pages) describe Prenot@Mi as the online booking system for visa appointments.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = true where id = 'it-maeci-prenotami';
update internal.sources set summary = 'Foreign Ministry ''Il visto per l''Italia'' home page. It offers a four-question guided check (nationality, country of residence, length of stay, purpose) to tell whether a visa is needed and which forms apply. It says the information is only indicative and not exhaustive, that applicants should contact the Italian mission for their place of residence, that submitting documents does not necessarily mean a visa is issued, and that border authorities may ask again for proof of the visa requirements. It also notes the EU Entry/Exit System (EES) from 12 October 2025 for short stays. The purpose list shown does not include a digital-nomad option.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-maeci-visti-portal';
update internal.sources set summary = 'Normattiva page for D.Lgs. 25 July 1998 n. 286, the consolidated immigration act (Testo unico), last updated for acts published 1 July 2026. The landing page shows the act''s preamble and Art. 1: the Testo unico applies, unless otherwise provided, to non-EU citizens and stateless persons, not to EU citizens, and an implementing regulation is issued under it. The full act is reachable from this page article by article; specific articles (e.g. art. 4 on entry, art. 27-quater) are separate source rows.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = true where id = 'it-normattiva-dlgs-286-1998';
update internal.sources set summary = 'Normattiva text of art. 27-quater D.Lgs. 286/1998 (in force from 18 Dec 2025), on highly qualified workers and the EU Blue Card. Comma 1 lists the alternative qualifications: a tertiary degree of at least three years or a post-secondary qualification of at least three years or EQF/QNQ level 6; the requirements of D.Lgs. 206/2007 for regulated professions; a higher professional qualification shown by at least five years of comparable experience; or, for ICT managers and specialists (ISCO-08 133 and 25), at least three years of relevant experience in the seven years before applying. The rest covers the Blue Card procedure, refusals, and Blue Card family reunification.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-normattiva-dlgs-286-1998-art27quater';
update internal.sources set summary = 'Normattiva text of art. 4 D.Lgs. 286/1998 (entry into Italy). Entry needs a valid passport or equivalent travel document and a valid visa, travel authorisation, or permesso, under Schengen rules, through official border crossings. Visas are issued by Italian missions in the country of origin or stable residence. Comma 3: the foreigner must show documents confirming purpose and conditions of stay and sufficient means; entry is refused to those seen as a threat to public order or security or convicted of listed offences. Comma 4-bis: national-visa applicants give biometric identifiers, subject to exemptions set by ministerial decree. False documents make the application inadmissible. It also covers EES and ETIAS.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-normattiva-dlgs-286-1998-art4';
update internal.sources set summary = 'Polizia di Stato page (24 Jun 2014, modified 5 Jan 2024) on issuing the permesso di soggiorno. First arrivals have 8 working days to request it from the Questore of the province where they intend to stay, in some cases via authorised post offices. Issue and renewal take on average 60 days. You bring the request form, passport with visa and a copy, 4 identical photos, documents for the permit type, and the fee. Contribution: €40 for permits over three months up to one year, €50 over one to two years, €100 for some others; minors are exempt. A minor child gets an individual electronic permit. Permits of at least one year require an integration agreement. It does not mention the digital-nomad permit specifically.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'it-polizia-permesso-issue';
update internal.sources set summary = 'Boston consulate page for the digital nomad / remote worker visa. Two categories (nomads: freelancers; remote workers: employees), work meeting art. 27-quater. Documents include: passport valid 15 months past travel with two blank pages; proof of residence in the jurisdiction; visa form and photo; travel medical insurance of at least €30,000 or $50,000; proof of qualifying profession; a lease, rental contract, or deed in the applicant''s name for the whole visa (hotel or hospitality not accepted); income of at least three times the healthcare-exemption minimum, printed as €24,789 ''at the time of this writing in 2024'', from the work, not passive income; six months'' experience. Remote workers add a contract and employer no-convictions letter. No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-boston-dnv';
update internal.sources set summary = 'Chicago consulate PDF checklist (file ''SF_DIGITAL-NOMAD-VISA_Rev. 17-05-2024'', uploaded 2024/08). It lists: passport valid 15 months past travel with two blank pages; proof of residence in the jurisdiction; visa form and photo; travel medical insurance of at least €30,000 or $50,000 (or Italian policy/affidavit); proof of qualifying profession; a lease, rental contract, or deed in the applicant''s name for the whole visa, registered if leased, and says hospitality or a hotel is unacceptable; income of at least three times the healthcare-exemption minimum, €24,789 ''at the time of this writing in 2024''; six months'' experience. Remote workers add a contract and employer letter. It covers family sponsorship and the permesso. No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = true where id = 'us-chicago-dnv-checklist-pdf';
update internal.sources set summary = 'Detroit consulate PDF checklist (uploaded 2024/05). It lists: passport valid 15 months past travel with two blank pages; proof of residence in the jurisdiction; visa form and photo; travel medical insurance of at least €30,000 or $50,000 (or proof of an Italian policy); proof of qualifying profession; a lease, rental contract, or deed in the applicant''s name for the whole visa, hotel or hospitality unacceptable; income of at least three times the healthcare-exemption minimum, €24,789 ''at the time of this writing in 2024''; six months'' experience. Remote workers add a contract and employer letter. Spouse and minor-child sponsorship starts at the Questura (2024 wording). No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-detroit-dnv-checklist-pdf';
update internal.sources set summary = 'Houston consulate page for the digital nomad / remote worker visa. It says the visa is for highly specialized workers meeting art. 27-quater, in two categories (digital nomads: freelancers and independent specialists; remote workers: employees working fully remotely). The checklist itself is a linked document. Payment is by USPS money order only. It links the national visa form, a medical-insurance affidavit, and a remote-worker employer declaration. Appointments for a national visa are booked on Prenot@Mi, stating it is for Digital Nomad or Remote Work. Processing may take up to 120 days for self-employed applicants and up to 30 days for subordinate workers.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = true where id = 'us-houston-dnv';
update internal.sources set summary = 'Los Angeles consulate extract of the consular fee table for 1 October to 31 December 2026, at an exchange rate of €1.00 = $1.1516. It lists passport, ID card, notarial, citizenship, and translation fees, and visa fees: Schengen visa €90.00 ($103.70), Schengen for minors 6-12 €45.00 ($51.90), national long-stay visa type D €116.00 ($133.60), and national study visa €50.00 ($57.60). The amounts apply to that quarter only.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-los-angeles-consular-tariff-q4-2026';
update internal.sources set summary = 'Los Angeles consulate page for the digital nomad / remote worker visa. From 11 January 2025 all national-visa applicants are fingerprinted. Documents include: passport valid 15 months past travel; proof of residence in the jurisdiction; visa form and photo; travel medical insurance of at least €30,000 or $50,000; proof of qualifying profession; a lease, rental contract, or deed in the applicant''s name for the whole visa, registered if leased; income of at least three times the healthcare-exemption minimum, ''€24,789 at the time of this writing''; six months'' experience; a quarterly-adjusted fee. Remote workers add a contract and employer letter. Spouse and children under 18 can be sponsored once in Italy via the Questura (2024 wording). No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-los-angeles-dnv';
update internal.sources set summary = 'Miami consulate PDF (uploaded 2024/05) for the self-employed digital nomad visa. General items: fee by money order (adjusts quarterly), passport valid 3 months beyond the stay (at least one year past arrival), proof of residence in the jurisdiction, visa form, photo, mailing items, and copies. Specific items: evidence of highly skilled status under art. 27-quater (apostilled degree with CIMEA, regulated-profession recognition, or apostilled proof of experience); lawful income at least three times the healthcare-exemption minimum (no euro figure); health insurance valid in Italy with at least €30,000; legal proof of accommodation such as a registered lease; six months'' experience. For family visas it points to vistoperitalia.esteri.it. No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-miami-dn-self-employed-pdf';
update internal.sources set summary = 'Miami consulate PDF (uploaded 2024/05) for the remote worker (subordinate work) visa. It defines the remote worker as doing subordinate work or collaboration remotely under D.Lgs. 81/2015, for an employer in Italy or abroad. Same general items as the Miami nomad sheet, plus: art. 27-quater evidence (apostilled, CIMEA); lawful income at least three times the healthcare-exemption minimum (no euro figure); Italy-valid health insurance of at least €30,000; legal proof of accommodation such as a registered lease; six months'' experience; a contract or binding offer at least at collective-agreement pay, considering ISTAT; and a notarized employer affidavit of no listed convictions in five years, with ID. Family visas: see vistoperitalia.esteri.it. No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-miami-rw-subordinate-pdf';
update internal.sources set summary = 'New York consulate page for the digital nomad / remote worker visa. Documents include: passport valid 15 months past travel with two blank pages; proof of residence in the jurisdiction; visa form and photo; travel medical insurance of at least €30,000 or $50,000 (or Italian policy/affidavit); proof of qualifying profession; a lease, rental contract, or deed in the applicant''s name for the whole visa, registered if leased; it says a hospitality offer or hotel stay is unacceptable and it is denied without a lease or deed; income of at least three times the healthcare-exemption minimum, €24,789 ''at the time of this writing in 2024''; six months'' experience. Remote workers add a contract and employer letter. Family sponsorship starts at the Questura. No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-new-york-dnv';
update internal.sources set summary = 'New York consulate general visa information. Appointments are online only via Prenot@Mi, free, and must be confirmed 3 to 10 days before; a waiting list exists; you can book at most 180 days before departure; applicants appear in person. Only residents of the listed jurisdiction (NY, CT, certain NJ counties, Bermuda) may apply, with proof such as a driver''s license. Non-US citizens show US legal residence. Passport valid 3 months beyond the trip with two visa pages. Processing generally varies from 7 days to several weeks. Fees by money order or certified check; they change every 3 months. Originals plus copies; passports returned by USPS prepaid envelope only. Minors need a birth certificate, notarized parental consent, and both parents present.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-new-york-visa-general';
update internal.sources set summary = 'Philadelphia consulate page listing many visa categories, including a digital nomad / remote worker section. That section lists: passport valid 15 months past travel; proof of residence; visa form and photo; travel medical insurance of at least €30,000 or $50,000; proof of qualifying profession; a lease, rental contract, or deed in the applicant''s name for the whole visa; registered if leased; hospitality or a hotel is unacceptable; income of at least three times the healthcare-exemption minimum, €24,789 ''at the time of this writing in 2024''; six months'' experience. Remote workers add a contract and employer letter. Spouse and children under 18 can be sponsored via the Questura (2024 wording). It warns incomplete files are not accepted. No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-philadelphia-visa-categories';
update internal.sources set summary = 'San Francisco consulate PDF checklist (uploaded 2024/05). It lists: passport valid 15 months past travel with two blank pages; proof of residence in the jurisdiction; visa form and photo; travel medical insurance of at least €30,000 or $50,000; proof of qualifying profession; a lease, rental contract, or deed in the applicant''s name for the whole visa, registered if leased; income of at least three times the healthcare-exemption minimum, €24,789 ''at the time of this writing in 2024''; six months'' experience. Remote workers add a contract and employer letter. Spouse and children under 18 can be sponsored once in Italy, starting at the Questura (2024 wording). It covers the permesso. No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-san-francisco-dnv-checklist-pdf';
update internal.sources set summary = 'Italian Embassy in Washington page (last updated 14 October 2026) listing the first-category Italian consulates in the US and their jurisdictions: Boston, Chicago, Detroit, Philadelphia, Houston, Los Angeles, Miami, New York, San Francisco, and Washington (the Embassy''s consular section), each with address, contacts, website, and the states or counties it covers. It also has a section on the US honorary consular network.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-washington-consular-network';
update internal.sources set summary = 'Washington Embassy PDF checklist (uploaded 2026/02). It lists: visa form matching the passport, photo, proof of residence in the jurisdiction, passport valid 15 months past travel with two blank pages; travel medical insurance of at least €30,000 or $50,000; a lease, rental contract, or deed in the applicant''s name for the whole visa, registered if leased; six months'' experience; proof of qualifying profession; income of at least three times the healthcare-exemption minimum, €24,789 ''at the time of this writing in 2024''; fee by money order or cashier''s check. Remote workers add a contract with gross salary not below €33,000 and an employer letter on the Embassy form. Qualification documents from non-EU bodies must be legalized or apostilled and translated. No police certificate is listed.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-washington-dnv-checklist-pdf';
update internal.sources set summary = 'Washington Embassy page on booking visa appointments (last updated 9 June 2026). Elective-residence and digital nomad / remote worker applicants must email visti.washington@esteri.it before booking. In general, appointments are booked on Prenot@Mi, up to 6 months in advance and no later than 15 days before the intended departure. The office may cancel appointments booked by residents of other consular jurisdictions. Appointments must be confirmed on Prenot@Mi; if cancelled, a new one must be booked, which may delay departure.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = true where id = 'us-washington-visa-booking';
update internal.sources set summary = 'Washington Embassy visa fee page (last updated 2 October 2026). It says fees may vary from quarter to quarter. For 1 October to 31 December 2026: Schengen visa $103.70; Schengen for certain listed countries $40.40; visa for minors 6-12 $51.90; national visa over 90 days $133.60; national study visa $57.60. Payment is made at the consular office on the day of the appointment, by cashier''s check or money order to ''Embassy of Italy, Washington DC'', or exact cash.', summary_reviewed_at = '2026-10-16'::date, summary_uncertain = false where id = 'us-washington-visa-fees';

insert into internal.sources
  (id, path_ids, country, title, publisher, official_url, doc_type, scope, retrieved_at, status, notes, step_ids)
values
  ('us-houston-dnv-checklist-2026-docx', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'Digital nomad checklist 2026 (Houston, docx)', 'Consulate General of Italy Houston',
   'https://conshouston.esteri.it/wp-content/uploads/2026/07/DIGITAL-NOMAD-Checklist-2026.docx',
   'consular_guidance', 'US-consulate:houston', '2026-10-16'::date, 'inactive',
   'Uploaded Jul 2026, linked from us-houston-dnv. States a 2026 minimum legal income figure newer than the 2024 figure other posts print. INACTIVE until Visa Ops confirms the URL. Not cited.', array['proof-of-income']::text[]),
  ('it-normattiva-dlgs-286-1998-art29', array['italy_digital_nomad', 'italy_remote_worker']::text[], 'IT', 'D.Lgs. 286/1998 art. 29 – Ricongiungimento familiare', 'Normattiva',
   'https://www.normattiva.it/uri-res/N2Ls?urn:nir:stato:decreto.legislativo:1998-07-25;286~art29',
   'law', 'national', '2026-10-16'::date, 'active',
   'Read 2026-10-16 (WebFetch; JS-rendered, link check may false-fail). Comma 1(a) spouse not legally separated, 18+; 1(b) unmarried minor children incl. spouse''s / born outside marriage, other parent''s consent. Comma 3 housing/income conditions NOT stated in user copy until approved.', array['family-documents', 'family-permesso']::text[])
on conflict (id) do nothing;

